// ─── Mochi images (injected at build) ────────────────────────────
// MOCHI_GRUMPY and MOCHI_HAPPY injected by cat command

function Mochi({size=60,animate=false,mood="grumpy"}){
  const src = mood==="happy" ? MOCHI_HAPPY : MOCHI_GRUMPY;
  return(
    <div style={{width:size,height:size,flexShrink:0,
      ...(animate?{animation:"mochiFloat 3s ease-in-out infinite"}:{})}}>
      <img src={src} alt="Mochi" style={{width:"100%",height:"100%",objectFit:"contain"}}/>
    </div>
  );
}

// ─── Helpers ─────────────────────────────────────────────────────
function todayStr(){const d=new Date();return d.getFullYear()+"-"+(d.getMonth()+1)+"-"+d.getDate();}
function dailySeed(){const d=new Date();return d.getFullYear()*10000+(d.getMonth()+1)*100+d.getDate();}
function seededRand(seed,n){const x=Math.sin(seed+n)*10000;return x-Math.floor(x);}
function todayDow(){return new Date().getDay();}
const DAY_NAMES=["Sun","Mon","Tue","Wed","Thu","Fri","Sat"];

// ─── Grumpy meter ─────────────────────────────────────────────────
// 0=furious 20=grumpy 40=indifferent 60=tolerant 80=content 100=happy
function getMochiMood(grumpy){
  if(grumpy>=80) return "happy";
  if(grumpy>=60) return "tolerant";
  if(grumpy>=40) return "indifferent";
  return "grumpy";
}
function getGrumpyLabel(g){
  if(g>=80) return "Mochi is pleased";
  if(g>=60) return "Mochi tolerates you";
  if(g>=40) return "Mochi is indifferent";
  if(g>=20) return "Mochi is grumpy";
  return "Mochi is furious";
}
function getGrumpyColor(g){
  if(g>=80) return C.prod;
  if(g>=60) return "#a0c878";
  if(g>=40) return C.warn;
  if(g>=20) return "#e8844a";
  return "#e85a4a";
}

// ─── Quotes ──────────────────────────────────────────────────────
const QUOTES={
  struggling:["You haven't disappeared. That's your starting point. Use it.","Still here? Good. Now do one thing. Just one.","Momentum doesn't care about your mood. Only what you do next."],
  building:["You're moving. Slow is still forward.","Consistency is boring. That's exactly why it works.","Most people quit here. You haven't. That matters."],
  strong:["Impressive. Don't let it go to your head.","You've turned showing up into a habit. That's the whole game.","Good. Now do it again. That's how this works."],
};
function getMochiQuote(score){
  const pool=score<45?QUOTES.struggling:score<72?QUOTES.building:QUOTES.strong;
  return pool[Math.floor(seededRand(dailySeed(),7)*pool.length)];
}

