function getBreakdown(name){
  const l=name.toLowerCase();
  for(const r of RULES) if(r.kw.some(k=>l.includes(k))) return r.steps;
  return DEFAULT_STEPS;
}

// ─── History ─────────────────────────────────────────────────────
function genHistory(){
  const s=dailySeed();
  return Array.from({length:30},(_,i)=>({
    health:Math.round(seededRand(s,i*3+1)*60+30),
    home:Math.round(seededRand(s,i*3+2)*60+30),
    prod:Math.round(seededRand(s,i*3+3)*60+25),
  }));
}
const HISTORY=genHistory();

