// Check which achievements are earned based on stats
function checkAchievements(stats, earned){
  const newEarned = [...earned];
  const add = id => { if(!newEarned.includes(id)) newEarned.push(id); };

  if(stats.totalHabits>=1)   add("first_habit");
  if(stats.totalSprints>=1)  add("first_sprint");
  if(stats.waterCount>=1)    add("first_water");
  if(stats.bedCount>=1)      add("first_bed");
  if(stats.planCount>=1)     add("first_plan");
  if(stats.habitsToday>=3)   add("three_habits");
  if(stats.habitsToday>=5)   add("five_habits");
  if(stats.fullDaysToday)    add("full_day");
  if(stats.healthDayToday)   add("health_day");
  if(stats.homeDayToday)     add("home_day");
  if(stats.focusDayToday)    add("focus_day");
  if(stats.totalSprints>=5)  add("five_sprints");
  if(stats.totalSprints>=10) add("ten_sprints");
  if(stats.totalSprints>=50) add("fifty_sprints");
  if(stats.waterCount>=10)   add("ten_water");
  if(stats.waterCount>=50)   add("fifty_water");
  if(stats.totalHabits>=20)  add("twenty_habits");
  if(stats.totalHabits>=100) add("hundred_habits");
  if(stats.totalHabits>=5)   add("add_five");
  if(stats.fullDaysCount>=3) add("three_full");
  if(stats.fullDaysCount>=7) add("seven_full");
  if(stats.grumpyMeter>=60)  add("grumpy60");
  if(stats.grumpyMeter>=80)  add("grumpy80");
  if(stats.grumpyMeter>=100) add("grumpy100");

  return newEarned;
}

