function MomentumRing({h,ho,p,size=160}){
  const cx=size/2,cy=size/2;
  const r1=cx*0.88,r2=cx*0.70,r3=cx*0.52,sw=11;
  const arc=r=>2*Math.PI*r;
  const off=(pct,r)=>arc(r)-arc(r)*pct/100;
  const total=Math.round((h+ho+p)/3);
  return(
    <div style={{position:"relative",width:size,height:size,flexShrink:0}}>
      <svg viewBox={"0 0 "+size+" "+size} style={{position:"absolute",top:0,left:0,right:0,bottom:0,width:"100%",height:"100%",transform:"rotate(-90deg)"}}>
        {[[r1,C.health,h],[r2,C.home,ho],[r3,C.prod,p]].map(([r,color,pct],i)=>(
          <g key={i}>
            <circle cx={cx} cy={cy} r={r} fill="none" stroke="#1a1230" strokeWidth={sw}/>
            <circle cx={cx} cy={cy} r={r} fill="none" stroke={color} strokeWidth={sw}
              strokeDasharray={arc(r)} strokeDashoffset={off(pct,r)} strokeLinecap="round"
              style={{transition:"stroke-dashoffset 0.7s ease"}}/>
          </g>
        ))}
      </svg>
      <div style={{position:"absolute",top:0,left:0,right:0,bottom:0,display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center"}}>
        <div style={{fontSize:22,fontWeight:700,color:C.txt,lineHeight:1}}>{total}%</div>
        <div style={{fontSize:9,color:C.txt3,marginTop:3,letterSpacing:"0.1em",textTransform:"uppercase"}}>Momentum</div>
      </div>
    </div>
  );
}

function SparkBars({data,color,height=36}){
  return(
    <svg width="100%" height={height} viewBox={"0 0 "+(data.length*6)+" "+height} preserveAspectRatio="none">
      {data.map((v,i)=>(
        <rect key={i} x={i*6} y={height-(v/100)*height} width="4" height={(v/100)*height}
          fill={color} opacity={0.25+(v/100)*0.75} rx="1"/>
      ))}
    </svg>
  );
}

// ─── Grumpy Meter Component ───────────────────────────────────────
function GrumpyMeter({value}){
  const color=getGrumpyColor(value);
  const label=getGrumpyLabel(value);
  return(
    <div style={{background:C.surf,border:"0.5px solid "+C.border2,borderRadius:14,padding:"12px 14px"}}>
      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:8}}>
        <div style={{fontSize:11,color:C.txt3,fontWeight:600,textTransform:"uppercase",letterSpacing:"0.06em"}}>Grumpy Meter</div>
        <div style={{fontSize:12,color:color,fontWeight:700}}>{value}/100</div>
      </div>
      <div style={{background:"#0d0a18",borderRadius:8,height:10,overflow:"hidden",marginBottom:6}}>
        <div style={{height:"100%",width:value+"%",borderRadius:8,
          background:"linear-gradient(90deg,#e85a4a,"+color+")",
          transition:"width 0.6s ease"}}/>
      </div>
      <div style={{fontSize:11,color:color,fontStyle:"italic"}}>{label}</div>
    </div>
  );
}

// ═══ FEED MOCHI MODAL ═══════════════════════════════════════════
